export function operationDefinition(classType) {
  return OPERATION_REGISTRY[String(classType || "")] || null;
}

export function operationActions(classType, sourceRole = "") {
  const definition = operationDefinition(classType);
  if (!definition) return [];
  const roleActions = definition.actionsBySourceRole?.[sourceRole];
  return (roleActions || definition.actions || []).map((value) => ({ ...value }));
}

export function operationLabel(classType) {
  return operationDefinition(classType)?.label || String(classType || "Operation");
}
